# SaleHop: "show every ad" mode, ad detail pages, advertiser self-edit
# accounts, plus a new database migration
#
# What this adds:
#  1. Ad Frequency = 0 in /admin is now a special "show every active ad"
#     mode, for slow/sparse sale days -- Browse appends every active ad
#     after the real sales feed instead of mixing one in every N listings.
#     The old 1-50 validation now allows 0, and the admin hint text
#     explains what 0 does.
#  2. Every ad now gets a real, individually shareable page at
#     salehop.app/ad/[id] -- same Open-Graph-tagged pattern as a sale's
#     /listing/[id] page. Reachable from /admin's ad row ("View Page") and
#     from an owner's own "My Ad" section (see #3). Tapping an ad card in
#     Browse still opens the sponsor's link directly, unchanged -- this
#     new page is for sharing/reference, not a replacement for that.
#  3. A business owner can now sign in and edit their own ad. Type an
#     email into the new "Owner email" field on an ad in /admin, and that
#     business can sign in with that exact email (the same magic-link/
#     password seller accounts that already exist -- no separate
#     advertiser signup) and see a new "My Ad" section on their Account
#     tab with an Edit button. They can change title, description, image,
#     link, sponsor name, and location/address -- edits go live
#     immediately, no approval needed. They CANNOT change the ad's type,
#     its raw embed code, its owner email, or its active/paused status --
#     those stay admin-only on purpose (enforced by a database trigger,
#     not just hidden in the UI).
#
# Includes a new database migration, supabase/schema-v12-ad-ownership.sql
# -- run it once in the Supabase SQL Editor (Project -> SQL Editor -> New
# query -> paste the file's contents -> Run) to actually enable the
# "Owner email" field and advertiser sign-in. Everything else in this
# update works immediately without it; the admin ad create/edit routes
# detect the not-yet-existing column and gracefully skip it until the
# migration is run, so this is safe to deploy in either order.
#
# Touches: components/AppShell.js, components/BrowseScreen.js,
# components/AccountScreen.js, components/AdForm.js, app/admin/page.js,
# app/api/admin/settings/route.js, app/api/admin/ads/route.js,
# app/api/admin/ads/[id]/route.js. Adds: supabase/schema-v12-ad-
# ownership.sql, lib/getAdForShare.js, app/ad/[id]/page.js,
# components/AdOwnerForm.js. No new npm package.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

